/**
 * Worker entry: canonical host redirect, then the OpenNext (Next.js) handler.
 * lulox.dev -> https://www.lulox.dev (307, same as the old Vercel domain redirect).
 */
// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

const APEX = "lulox.dev";
const CANONICAL = "www.lulox.dev";

export default {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const url = new URL(request.url);
    if (url.hostname === APEX) {
      url.hostname = CANONICAL;
      url.protocol = "https:";
      return Response.redirect(url.toString(), 307);
    }
    return handler.fetch(request, env, ctx);
  },
};

// @ts-expect-error generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
